import unittest
import basic_setting as app

class Behavior(unittest.TestCase):
    def test_escapes(self):
        for s,w in [('"dock"','dock'),('"a\\nb"','a\nb'),('"a\\t\\r\\b\\f"','a\t\r\b\f'),('"\\u6E2F\\U0001F6A2"','港🚢'),('"\\\\n"','\\n'),('"say \\"yes\\""','say "yes"')]:
            self.assertEqual(app.decode_basic(s),w)
        for s in ['"bad\\q"','"bad\\/"','"\\uD800"','"\\U00110000"']:
            with self.assertRaises(ValueError):app.decode_basic(s)


if __name__ == "__main__":
    unittest.main()

class Version10Escapes(unittest.TestCase):
    def test_reserved_and_literal_backslash(self):
        for s in [r'"\e"', r'"\x41"', r'"\v"', r'"\u12G4"', r'"\U0000DFFF"']:
            with self.subTest(text=s), self.assertRaises(ValueError): app.decode_basic(s)
        self.assertEqual(app.decode_basic(r'"\\e"'), '\\e')
        self.assertEqual(app.decode_basic('"港\t口"'), '港\t口')

