import re
import tomllib

def decode_basic(text):
    # Pin the escape alphabet to TOML 1.0 even on newer Python parsers.
    for escape in re.finditer(r'\\([\s\S])', text[1:-1]):
        if escape[1] not in 'btnfr"\\uU':
            raise ValueError('reserved escape')
    try:
        return tomllib.loads('value = ' + text)['value']
    except tomllib.TOMLDecodeError as error:
        raise ValueError('invalid basic string') from error
